  6277  int load_protocols_file_fd(struct ndpi_detection_module_struct *ndpi_str, FILE *fd) {
  6278    char *buffer, *old_buffer;
  6279    int chunk_len = 1024, buffer_len = chunk_len, old_buffer_len;
  6280    int i;
  6281
  6282    if(!ndpi_str || !fd)
  6283      return -1;
  6284
  6285    buffer = ndpi_malloc(buffer_len);
  6286    if(buffer == NULL) {
  6287      NDPI_LOG_ERR(ndpi_str, "Memory allocation failure\n");
  6288      return -2;
  6289    }
  6290
  6291    while(1) {
  6292      char *line = buffer;
  6293      int line_len = buffer_len;
  6294
  6295      while(((line = fgets(line, line_len, fd)) != NULL)
  6296            && strlen(line) > 0
  6297            && (line[strlen(line) - 1] != '\n')) {
  6298        i = strlen(line);
  6299        old_buffer = buffer;
  6300        old_buffer_len = buffer_len;
  6301        buffer_len += chunk_len;
  6302
  6303        buffer = ndpi_realloc(old_buffer, old_buffer_len, buffer_len);
  6304        if(buffer == NULL) {
  6305          NDPI_LOG_ERR(ndpi_str, "Memory allocation failure\n");
  6306          ndpi_free(old_buffer);
  6307          return -2;
  6308        }
  6309
  6310        line = &buffer[i];
  6311        line_len = chunk_len;
  6312      } /* while */
  6313
  6314      if(!line) /* safety check */
  6315        break;
  6316
  6317      i = strlen(buffer);
  6318      if((i <= 1) || (buffer[0] == '#'))
  6319        continue;
  6320      else {
  6321        buffer[i - 1] = '\0';
  6322        i--;
  6323
  6324        if((i > 0) && (buffer[i-1] == '\r'))
  6325          buffer[i - 1] = '\0';
  6326
  6327        if(buffer[0] == '\0')
  6328          continue;
  6329      }
  6330
  6331      /* printf("Processing: \"%s\"\n", buffer); */
  6332
  6333      if(ndpi_handle_rule(ndpi_str, buffer) != 0)
  6334        NDPI_LOG_INFO(ndpi_str, "Discraded rule '%s'\n", buffer);
  6335    }
  6336
  6337    ndpi_free(buffer);
  6338
  6339    return 0;
  6340  }
