  5542  /*
  5543   * Format:
  5544   *
  5545   * <proto,param,value>
  5546   *
  5547   * Notes:
  5548   *  - proto might be empty
  5549   *  - empty lines or lines starting with # are ignored
  5550   */
  5551  int load_config_file_fd(struct ndpi_detection_module_struct *ndpi_str, FILE *fd) {
  5552    char buffer[512], *line, *proto, *param = NULL, *value, *saveptr;
  5553    int len, i, num_commas;
  5554    ndpi_cfg_error rc;
  5555
  5556    if(!ndpi_str || !fd)
  5557      return -1;
  5558
  5559    while(1) {
  5560      line = fgets(buffer, sizeof(buffer), fd);
  5561
  5562      if(line == NULL)
  5563        break;
  5564
  5565      len = strlen(line);
  5566
  5567      if((len <= 1) || (line[0] == '#'))
  5568        continue;
  5569
  5570      line[len - 1] = '\0';
  5571
  5572      /* First parameter might be missing */
  5573      num_commas = 0;
  5574      for(i = 0; i < len; i++) {
  5575        if(line[i] == ',')
  5576          num_commas++;
  5577      }
  5578
  5579      if(num_commas == 1) {
  5580        proto = NULL;
  5581        param = strtok_r(line, ",", &saveptr);
  5582      } else if(num_commas == 2) {
  5583        proto = strtok_r(line, ",", &saveptr);
  5584        if(proto) {
  5585          param = strtok_r(NULL, ",", &saveptr);
   580                                       ndpi_str, NDPI_LOG_DEBUG, _file, _func, _line, "exclude %s\n",
   581                                       ndpi_str->callback_buffer[dissector_idx].name);
   582    }
   583  #else
   584    (void)ndpi_str;
   585    (void)_file;
   586    (void)_func;
   587    (void)_line;
   588  #endif
   589    dissector_bitmask_set(&flow->excluded_dissectors_bitmask, dissector_idx);
   590  }
