   594  int is_proto_enabled(struct ndpi_detection_module_struct *ndpi_str, int protoId)
   595  {
   596    if(protoId < 0)
   597      return 0;
   598    /* Custom protocols are always enabled */
   599    if(ndpi_is_custom_protocol(ndpi_str, protoId))
   600      return 1;
   601    /* By default, all protocols are enabled */
   602    if(ndpi_str->detection_bitmask == NULL)
   603      return 1;
   604    if(ndpi_bitmask_is_set(ndpi_str->detection_bitmask, protoId))
   605      return 1;
   606    return 0;
   607  }
