   611  void ndpi_set_proto_subprotocols(struct ndpi_detection_module_struct *ndpi_str, int protoId, ...)
   612  {
   613    va_list ap;
   614    int current_arg = protoId;
   615    size_t i = 0;
   616
   617    va_start(ap, protoId);
   618    while (current_arg != NDPI_PROTOCOL_NO_MORE_SUBPROTOCOLS) {
   619      ndpi_str->proto_defaults[protoId].subprotocol_count++;
   620      current_arg = va_arg(ap, int);
   621    }
   622    va_end(ap);
   623
   624    ndpi_str->proto_defaults[protoId].subprotocols = NULL;
   625
   626    /* The last protocol is not a subprotocol. */
   627    ndpi_str->proto_defaults[protoId].subprotocol_count--;
   628    /* No subprotocol was set before NDPI_NO_MORE_SUBPROTOCOLS. */
   629    if(ndpi_str->proto_defaults[protoId].subprotocol_count == 0) {
   630      return;
   631    }
   632
   633    ndpi_str->proto_defaults[protoId].subprotocols =
   634      ndpi_malloc(sizeof(protoId) * ndpi_str->proto_defaults[protoId].subprotocol_count);
   635    if(!ndpi_str->proto_defaults[protoId].subprotocols) {
   636      ndpi_str->proto_defaults[protoId].subprotocol_count = 0;
   637      return;
   638    }
   639
   640    va_start(ap, protoId);
   641    current_arg = va_arg(ap, int);
   642
   643    while (current_arg != NDPI_PROTOCOL_NO_MORE_SUBPROTOCOLS) {
   644      ndpi_str->proto_defaults[protoId].subprotocols[i++] = current_arg;
   645      current_arg = va_arg(ap, int);
   646    }
   647
   648    va_end(ap);
   649  }
