   653  static void load_default_ports(struct ndpi_detection_module_struct *ndpi_str)
   654  {
   655    unsigned int protoId;
   656    int j;
   657
   658    for(protoId = 0; protoId < ndpi_str->num_supported_protocols; protoId++) {
   659      if(!is_proto_enabled(ndpi_str, protoId)) {
   660        NDPI_LOG_DBG(ndpi_str, "Skip default ports for protoId=%d: disabled\n",
   661                     ndpi_str->proto_defaults[protoId].protoName, protoId);
   662        continue;
   663      }
   664
   665      for(j = 0; j < MAX_DEFAULT_PORTS; j++) {
   666        if(ndpi_str->proto_defaults[protoId].udp_default_ports[j].port_low != 0)
   667          addDefaultPort(ndpi_str, &ndpi_str->proto_defaults[protoId].udp_default_ports[j],
   668                         protoId, ndpi_str->proto_defaults[protoId].isCustomProto, &ndpi_str->udpRoot);
   669
   670        if(ndpi_str->proto_defaults[protoId].tcp_default_ports[j].port_low != 0)
   671          addDefaultPort(ndpi_str, &ndpi_str->proto_defaults[protoId].tcp_default_ports[j],
   672                         protoId, ndpi_str->proto_defaults[protoId].isCustomProto, &ndpi_str->tcpRoot);
   673      }
   674    }
   675  }
