   678
   679  static void ndpi_set_proto_defaults(struct ndpi_detection_module_struct *ndpi_str,
   680                                      u_int8_t is_cleartext, u_int8_t is_app_protocol,
   681                                      ndpi_protocol_breed_t breed,
   682                                      u_int16_t protoId, char *protoName,
   683                                      ndpi_protocol_category_t protoCategory,
   684                                      ndpi_protocol_qoe_category_t qoeCategory,
   685                                      ndpi_port_range *tcpDefPorts,
   686                                      ndpi_port_range *udpDefPorts,
   687                                      u_int8_t is_custom_protocol) {
   688    int j;
   689
   690
   691    /* There is no real limit on protocols number/id; the hard limit being the u_int16_t
   692       data typer used for the ids...
   693     */
   694
   695    if(protoId >= ndpi_str->proto_defaults_num_allocated) {
   696      int new_num;
   697      ndpi_proto_defaults_t *new_ptr;
   698
   699      new_num = ndpi_max(512, ndpi_nearest_power_of_two(protoId + 1));
   700      new_ptr = ndpi_realloc(ndpi_str->proto_defaults,
   701                             ndpi_str->proto_defaults_num_allocated * sizeof(ndpi_proto_defaults_t),
   702                             new_num * sizeof(ndpi_proto_defaults_t));
   703      if(!new_ptr) {
   704        NDPI_LOG_DBG(ndpi_str, "Realloc error\n");
   705        return;
   706      }
   707      memset(&new_ptr[ndpi_str->proto_defaults_num_allocated],
   708             '\0',
   709             sizeof(ndpi_proto_defaults_t) * (new_num - ndpi_str->proto_defaults_num_allocated));
   710      ndpi_str->proto_defaults = new_ptr;
   711      ndpi_str->proto_defaults_num_allocated = new_num;
   712    }
   713
   714    if(ndpi_str->proto_defaults[protoId].protoName[0] != '\0') {
   715      if(strcasecmp(ndpi_str->proto_defaults[protoId].protoName, protoName) != 0) {
   716        NDPI_LOG_ERR(ndpi_str, "Error. Same protocol id %d with different names [%s][%s]!\n",
   717                     protoId, ndpi_str->proto_defaults[protoId].protoName, protoName);
   718      } else {
   719        NDPI_LOG_DBG2(ndpi_str, "[NDPI] %s/protoId=%d: already initialized. Ignoring it\n", protoName, protoId);
   720      }
   721      return;
   722    }
   723
   724    strncpy(ndpi_str->proto_defaults[protoId].protoName,
   725            protoName,
   726            sizeof(ndpi_str->proto_defaults[protoId].protoName) - 1);
   727    ndpi_str->proto_defaults[protoId].protoName[sizeof(ndpi_str->proto_defaults[protoId].protoName) - 1] = '\0';
   728
   729    ndpi_str->proto_defaults[protoId].isClearTextProto = is_cleartext;
   730    /*

730    /*
   731      is_appprotocol=1 means that this is only an application protocol layered
   732      on top of a network protocol. Example WhatsApp=1, TLS=0
   733    */
   734    ndpi_str->proto_defaults[protoId].isAppProtocol = is_app_protocol;
   735    ndpi_str->proto_defaults[protoId].isCustomProto = is_custom_protocol;
   736    ndpi_str->proto_defaults[protoId].protoCategory = protoCategory;
   737    ndpi_str->proto_defaults[protoId].protoId = protoId;
   738    ndpi_str->proto_defaults[protoId].protoBreed = breed;
   739    ndpi_str->proto_defaults[protoId].qoeCategory = qoeCategory;
   740    ndpi_str->proto_defaults[protoId].subprotocols = NULL;
   741    ndpi_str->proto_defaults[protoId].subprotocol_count = 0;
   742    for(j = 0; j < MAX_DEFAULT_PORTS; j++) {
   743      ndpi_str->proto_defaults[protoId].tcp_default_ports[j] = tcpDefPorts[j];
   744      ndpi_str->proto_defaults[protoId].udp_default_ports[j] = udpDefPorts[j];
   745    }
   746
   747    ndpi_str->num_supported_protocols++;
   748    if(is_custom_protocol)
   749      ndpi_str->num_custom_protocols++;
   750    else
   751      ndpi_str->num_internal_protocols++;
   752  }
