   756  static int default_ports_tree_node_t_cmp(const void *a, const void *b) {
   757    default_ports_tree_node_t *fa = (default_ports_tree_node_t *) a;
   758    default_ports_tree_node_t *fb = (default_ports_tree_node_t *) b;
   759
   760    //printf("[NDPI] %s(%d, %d)\n", __FUNCTION__, fa->default_port, fb->default_port);
   761
   762    return((fa->default_port == fb->default_port) ? 0 : ((fa->default_port < fb->default_port) ? -1 : 1));
   763  }
   764
   765  /* ******************************************************************** */
   766
   767  static int addDefaultPort(struct ndpi_detection_module_struct *ndpi_str,
   768                            ndpi_port_range *range,
   769                            u_int16_t proto_idx,
   770                            u_int8_t customUserProto,
   771                            default_ports_tree_node_t **root) {
   772    u_int32_t port;
   773
   774    for(port = range->port_low; port <= range->port_high; port++) {
   775      default_ports_tree_node_t *node =
   776        (default_ports_tree_node_t *) ndpi_malloc(sizeof(default_ports_tree_node_t));
   777      default_ports_tree_node_t *ret;
   778
   779      if(!node) {
   780        NDPI_LOG_ERR(ndpi_str, "Not enough memory\n");
   781        break;
   782      }
   783
   784      node->proto_idx = proto_idx, node->default_port = port, node->customUserProto = customUserProto | range->is_custom;
   785      ret = (default_ports_tree_node_t *) ndpi_tsearch(node,
   786                                                       (void *) root,
   787                                                       default_ports_tree_node_t_cmp); /* Add it to the tree */
   788
   789      if(ret == NULL) {
   790        NDPI_LOG_ERR(ndpi_str, "Error searching for port %u\n", port);
   791        ndpi_free(node);
   792        break;
   793      }
   794
   795      if(ret != node) {
   796        NDPI_LOG_DBG(ndpi_str, "Found duplicate for port %u: overwriting it with new value\n",
   797                     port);
   798        /* Overwriting -> custom rules wins over "default"/hard-coded default ports */
   799
   800        ret->customUserProto |= (customUserProto | range->is_custom);
   801        ret->proto_idx = proto_idx;
   802        ndpi_free(node);
   803        return(-1); /* Duplicates found */
   804      }
   805    }
   806
   807    return(0);
   808  }
